<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';
$status=(int)($_SERVER['REDIRECT_STATUS']??($_GET['status']??404));
if(!in_array($status,[403,404],true))$status=404;
http_response_code($status);
header('Cache-Control: no-store, private');
header('X-Robots-Tag: noindex, nofollow',true);
function cc_err_ip(): string {$cf=(string)($_SERVER['HTTP_CF_CONNECTING_IP']??'');if($cf!==''&&filter_var($cf,FILTER_VALIDATE_IP))return $cf;$r=(string)($_SERVER['REMOTE_ADDR']??'unknown');return filter_var($r,FILTER_VALIDATE_IP)?$r:'unknown';}
function cc_err_clip(string $v,int $n): string {return mb_substr($v,0,$n);}
$ip=cc_err_ip();$path=parse_url((string)($_SERVER['REQUEST_URI']??'/'),PHP_URL_PATH)?:'/';$path=cc_err_clip($path,500);$method=cc_err_clip((string)($_SERVER['REQUEST_METHOD']??'GET'),12);$ua=cc_err_clip((string)($_SERVER['HTTP_USER_AGENT']??''),500);$ref=cc_err_clip((string)($_SERVER['HTTP_REFERER']??''),500);$requestId=bin2hex(random_bytes(8));
try{$pdo=cc_db();if($pdo){$pdo->exec("CREATE TABLE IF NOT EXISTS security_request_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id CHAR(16) NOT NULL UNIQUE,status_code SMALLINT UNSIGNED NOT NULL,ip_address VARCHAR(45) NOT NULL,path VARCHAR(500) NOT NULL,method VARCHAR(12) NOT NULL,user_agent VARCHAR(500) DEFAULT NULL,referer VARCHAR(500) DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_sec_ip_time(ip_address,created_at),INDEX idx_sec_status_time(status_code,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$st=$pdo->prepare("SELECT COUNT(*) FROM security_request_log WHERE ip_address=? AND created_at>=CURDATE()");$st->execute([$ip]);if((int)$st->fetchColumn()<100){$in=$pdo->prepare("INSERT INTO security_request_log(request_id,status_code,ip_address,path,method,user_agent,referer) VALUES(?,?,?,?,?,?,?)");$in->execute([$requestId,$status,$ip,$path,$method,$ua,$ref]);}if(random_int(1,100)===1)$pdo->exec("DELETE FROM security_request_log WHERE created_at<DATE_SUB(NOW(),INTERVAL 90 DAY)");}}
catch(Throwable $e){error_log('CostaCams error logger: '.$e->getMessage());}
$title=$status===403?'Restricted area':'Page not found';$message=$status===403?'This area is not public. The request has been recorded for security and diagnostics.':'That CostaCams page does not exist or the link is no longer valid.';
function h(string $v): string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=h($title)?> | CostaCams</title><style>:root{--bg:#050606;--panel:#0c1011;--line:#273035;--text:#eef4f5;--muted:#93a1a6;--aqua:#50dcff;--warn:#ffbf69}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 50% 0,#102a33,#050606 42%);color:var(--text);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}.card{width:min(680px,92vw);border:1px solid var(--line);border-radius:22px;background:linear-gradient(180deg,#101516,#090c0d);padding:28px;box-shadow:0 30px 80px #0008}.brand{font-weight:950;letter-spacing:.1em}.brand b{color:var(--aqua)}.code{font-size:76px;line-height:.9;font-weight:950;color:<?= $status===403?'var(--warn)':'var(--aqua)' ?>;letter-spacing:-.06em;margin:28px 0 8px}h1{font-size:30px;margin:0 0 8px}p{color:var(--muted)}.meta{margin:20px 0;padding:13px;border:1px solid #253238;border-radius:13px;background:#070a0b;font-size:12px;color:#9eafb4}.meta b{color:#e1ecef}.actions{display:flex;gap:9px;flex-wrap:wrap}.btn{display:inline-block;border:1px solid #344247;border-radius:999px;padding:9px 13px;color:#e9f4f7;text-decoration:none}.btn.primary{border-color:var(--aqua);color:#c9f7ff}</style></head><body><main class="card"><div class="brand"><b>COSTA</b>CAMS</div><div class="code"><?=$status?></div><h1><?=h($title)?></h1><p><?=h($message)?></p><div class="meta"><div><b>Your IP:</b> <?=h($ip)?></div><div><b>Request ID:</b> <?=h($requestId)?></div><div><b>Path:</b> <?=h($path)?></div></div><div class="actions"><a class="btn primary" href="/">Go to CostaCams</a><a class="btn" href="/map">Open map</a></div></main></body></html>